using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
namespace ClearSpace {
public static class Winapp2Tests {
 public static int Run(string output){Directory.CreateDirectory(output);var checks=new List<string>();Action<bool,string> check=(ok,text)=>{if(!ok)throw new Exception("FAILED: "+text);checks.Add("PASS: "+text);};Func<Action,bool> rejected=action=>{try{action();return false;}catch{return true;}};
 try{
  string fixture=Path.Combine(Path.GetFullPath(output),"winapp2-fixture-"+Guid.NewGuid().ToString("N")),local=Path.Combine(fixture,"LocalAppData"),cache=Path.Combine(local,"Example","Cache");Directory.CreateDirectory(Path.Combine(cache,"nested"));Directory.CreateDirectory(Path.Combine(cache,"private","sub"));
  var environment=new Winapp2Environment{Drive=Path.GetPathRoot(fixture),OSVersion=new Version(10,0,19045),AllowedBases=new[]{local},DeniedBases=new[]{Path.Combine(local,"Protected")}};environment.Variables["LocalAppData"]=new[]{local};environment.Variables["AppData"]=new[]{local};environment.Variables["UserProfile"]=new[]{fixture};environment.Variables["WinDir"]=new[]{Path.Combine(fixture,"Windows")};
  string sample="; Version: 260915\n[Example App Cache *]\nLangSecRef=3021\nDetectFile=%LocalAppData%\\missing\nDetectFile=%LocalAppData%\\Example\nFileKey1=%LocalAppData%\\Example\\Cache|*.log;*.tmp|RECURSE\nFileKey1=%LocalAppData%\\Example\\Cache|*.cache\nExcludeKey1=FILE|%LocalAppData%\\Example\\Cache\\|keep.log\nExcludeKey2=PATH|%LocalAppData%\\Example\\Cache\\private\\|*.tmp\nWarning=Rebuild required; preserve this entire warning.\nRegKey1=HKCU\\Software\\Example\\MRU\n";
  var pack=Winapp2Parser.Parse(sample);var entry=pack.Entries.Single();check(pack.Version=="260915"&&entry.Get("FileKey").Count()==2&&entry.Get("DetectFile").Count()==2,"Line parser preserves duplicate and numbered directives");check(entry.First("Warning").Contains("; preserve"),"Semicolons in masks and warnings are not stripped as inline comments");var key=Winapp2Parser.FileKey(entry.Get("FileKey").First());check(key.Masks.Length==2&&key.Recursive&&!key.RemoveSelf,"FileKey supports multiple masks and recursion");check(Regex.IsMatch("extensionless",Winapp2Parser.MaskRegex(new[]{"*.*"})),"Windows star-dot-star includes extensionless files");check(rejected(()=>Winapp2Parser.Parse("<html>unavailable</html>"))&&rejected(()=>Winapp2Parser.Parse("[bad]\nX=Y")),"HTML and files without cleaning directives are rejected");check(rejected(()=>Winapp2Parser.Parse("[dup]\nFileKey1=a|b\n[dup]\nFileKey2=a|b")),"Duplicate section names are rejected without merging exclusion scopes");check(rejected(()=>Winapp2Parser.FileKey(new IniDirective{Value="%LocalAppData%\\Example\\Cache|*|EXECUTE"})),"Unsupported file actions are never interpreted as deletion commands");check(rejected(()=>environment.Templates("%LocalAppData%\\..\\Documents"))&&rejected(()=>environment.Templates(@"C:\Documents\Cache")),"Path expansion rejects traversal and arbitrary absolute paths");check(rejected(()=>environment.Templates("%UNKNOWN%\\Cache")),"Unknown environment variables fail closed");
  check(Winapp2Adapter.OSMatches("6.1|",environment.OSVersion)&&!Winapp2Adapter.OSMatches("6.1|6.3",environment.OSVersion)&&Winapp2Adapter.OSMatches("10.0|10.0",environment.OSVersion),"DetectOS applies inclusive lower and upper version bounds");check(rejected(()=>Winapp2Adapter.OSMatches("nonsense|",environment.OSVersion)),"Malformed DetectOS constraints are rejected");string evidence;var discovery=new DiscoveryResult();check(Winapp2Adapter.Detected(entry,discovery,environment,CancellationToken.None,out evidence)&&evidence.Contains("Example"),"Repeated detection conditions use OR semantics");var registryEntry=Winapp2Parser.Parse("[Registry detection *]\nDetect=HKLM\\SYSTEM\\CurrentControlSet\nFileKey1=%LocalAppData%\\Example\\Cache|*.log\n").Entries[0];check(Winapp2Adapter.Detected(registryEntry,discovery,environment,CancellationToken.None,out evidence),"Registry detection is read-only and checks existing keys");var special=Winapp2Parser.Parse("[Chrome Cache *]\nSpecialDetect=DET_CHROME\nFileKey1=%LocalAppData%\\Example\\Cache|*.log\n").Entries[0];discovery.Applications.Add(new ApplicationIdentity{Name="Google Chrome",Executable="C:\\Apps\\chrome.exe"});check(Winapp2Adapter.Detected(special,discovery,environment,CancellationToken.None,out evidence),"Known SpecialDetect codes use discovered application fingerprints");special.Directives.First().Value="DET_UNKNOWN";check(!Winapp2Adapter.Detected(special,discovery,environment,CancellationToken.None,out evidence),"Unknown SpecialDetect codes do not broaden detection");
  var personal=Winapp2Parser.Parse(sample.Replace("Example App Cache","Saved Passwords"));check(Winapp2Adapter.Analyze(personal,environment).Supported==0,"Password sections stay protected even when targeting a cache directory");var broad=Winapp2Parser.Parse(sample.Replace("Example\\Cache|*.log;*.tmp","Example|*"));check(Winapp2Adapter.Analyze(broad,environment).Blocked>0,"Broad application-directory wipes are excluded");var unsupported=Winapp2Parser.Parse(sample+"MysteryAction=delete\n");check(Winapp2Adapter.Analyze(unsupported,environment).Supported==0,"Unknown directives preserve the entire cleaning scope");var invalidExclude=Winapp2Parser.Parse(sample.Replace("FILE|%LocalAppData%","FILE|%UNKNOWN%"));check(Winapp2Adapter.Analyze(invalidExclude,environment).Supported==0,"Invalid exclusions disable cleanup instead of being ignored");
  Action<string,string> write=(relative,contents)=>{string path=Path.Combine(cache,relative);File.WriteAllText(path,contents);File.SetLastWriteTimeUtc(path,DateTime.UtcNow.AddDays(-60));};write("old.log","old log");write("old.tmp","old temporary data");write("old.cache","old cache");write("nested\\nested.log","nested log");write("keep.log","preserved exclusion");write("private\\sub\\personal.tmp","protected subtree");write("document.tmp","%PDF personal data");write("config.json","config");write("data.sqlite-wal","database");write("Cookies.tmp","account");write("recent.tmp","recent");File.SetLastWriteTimeUtc(Path.Combine(cache,"recent.tmp"),DateTime.UtcNow);
  var rules=Winapp2Adapter.Resolve(pack,discovery,environment,CancellationToken.None,null);var executable=rules.Where(r=>!r.Protected).ToList();check(executable.Count==2&&executable.All(r=>!r.Quick&&r.ForceBackup&&r.Days==14),"Every community file rule is opt-in and requires a backup");check(rules.Any(r=>r.Protected&&r.Impact.Contains("注册表")),"RegKey actions are parsed and reported but never fed to arbitrary registry deletion");var engine=new Engine(rules){FileBackupDirectory=Path.Combine(fixture,"backups")};var findings=engine.Scan(CancellationToken.None,null);check(findings.Sum(f=>f.Candidates.Count)==4,"Scanning applies masks, age, exclusions, headers and sensitive-file protections");check(!executable[0].Accept(Path.Combine(cache,"private","sub","personal.tmp"))&&!executable[0].Accept(Path.Combine(cache,"keep.log")),"PATH and FILE exclusions apply at the deletion boundary");check(engine.Clean(findings,true,CancellationToken.None,null).Deleted==0,"One-click cleanup cannot include community rules");var result=engine.Clean(findings,false,CancellationToken.None,null);check(result.Deleted==4&&result.BackupFiles==4,"Advanced community cleanup forces backups even with permanent mode selected");check(FileRecovery.Restore(result.FileBackupManifest)==4&&File.Exists(Path.Combine(cache,"old.cache")),"Community cleanup backups restore exact original files");check(File.Exists(Path.Combine(cache,"keep.log"))&&File.Exists(Path.Combine(cache,"document.tmp"))&&File.Exists(Path.Combine(cache,"data.sqlite-wal")),"Excluded and personal content survives actual fixture cleanup");
  var recurse=Winapp2Parser.Parse(sample.Replace("RECURSE","REMOVESELF"));var recursiveRule=Winapp2Adapter.Resolve(recurse,discovery,environment,CancellationToken.None,null).First(r=>!r.Protected);check(!recursiveRule.OnlyTop&&recursiveRule.Impact.Contains("保留目录"),"REMOVESELF retains directories while adapting recursive file cleanup");var top=Winapp2Parser.Parse(sample.Replace("|RECURSE",""));var topRule=Winapp2Adapter.Resolve(top,discovery,environment,CancellationToken.None,null).First(r=>!r.Protected);check(topRule.OnlyTop,"Absent recursion flags only scan top-level files");
  var store=new Winapp2Store(Path.Combine(fixture,"rule-cache"));var bundled=store.Current();check(bundled.Entries.Count>3000&&bundled.FileKeys>10000&&bundled.RegistryKeys>3000,"Embedded upstream snapshot contains thousands of complete definitions");store.Import(sample);string active=File.ReadAllText(Path.Combine(store.DirectoryPath,"active.ini"));check(rejected(()=>store.Import("<html>broken</html>"))&&File.ReadAllText(Path.Combine(store.DirectoryPath,"active.ini"))==active,"Invalid updates do not replace the active INI");store.Import(sample.Replace("260915","260916"));check(store.Current().Version=="260916"&&store.Rollback().Version=="260915","INI updates keep an atomic previous version for rollback");check(rejected(()=>store.Import(sample.Replace("260915","250101"),true)),"Downloaded community rules cannot silently downgrade a dated version");var report=Winapp2Adapter.Analyze(bundled,Winapp2Environment.Windows());check(report.Supported+report.Blocked==bundled.FileKeys&&report.RegistryKeys==bundled.RegistryKeys,"Compatibility report accounts for every upstream file and registry instruction");File.WriteAllText(Path.Combine(output,"compatibility-summary.txt"),bundled.Version+" / "+report.Summary);
  string broadCache=Path.Combine(local,"Example","Cacheman");Directory.CreateDirectory(broadCache);File.WriteAllText(Path.Combine(broadCache,"valuable.dat"),"application content");var wildcardPack=Winapp2Parser.Parse("[Example Caches *]\nDetectFile=%LocalAppData%\\Example\nFileKey1=%LocalAppData%\\Example\\*Cache*|*|REMOVESELF\n");var wildcardRules=Winapp2Adapter.Resolve(wildcardPack,discovery,environment,CancellationToken.None,null);check(wildcardRules.Any(r=>r.Roots.Contains(cache))&&wildcardRules.All(r=>!r.Roots.Contains(broadCache)),"Wildcard expansion rechecks real directory names rather than trusting a cache-like pattern");
  environment.Variables["ProgramFiles"]=new[]{Path.Combine(fixture,"ProgramFiles64"),Path.Combine(fixture,"ProgramFiles32")};check(environment.Templates("%ProgramFiles%\\Example\\Cache").Length==2,"ProgramFiles variables can expand both architecture locations");var defaultPack=Winapp2Parser.Parse(sample+"Default=True\n");check(Winapp2Adapter.Resolve(defaultPack,discovery,environment,CancellationToken.None,null).All(r=>!r.Quick),"Default=True and section stars never opt community rules into one-click cleanup");
  string dataFile=Path.Combine(fixture,"bundled-copy.ini");File.Copy(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"rules","Winapp2.ini"),dataFile);check(Winapp2Store.BundledSnapshot(dataFile).Hash==bundled.Hash,"An intact standalone rule file loads the complete bundled snapshot");
  check(rejected(()=>Winapp2Store.BundledSnapshot(Path.Combine(fixture,"missing-bundle.ini"))),"A missing bundled rule file fails clearly rather than using an unrelated path");
  using(var writer=new FileStream(dataFile,FileMode.Open,FileAccess.ReadWrite,FileShare.ReadWrite|FileShare.Delete))check(rejected(()=>Winapp2Store.BundledSnapshot(dataFile)),"Bundled rule verification rejects concurrent writers");
  File.AppendAllText(dataFile,"\n; modified but still valid INI\n");check(rejected(()=>Winapp2Store.BundledSnapshot(dataFile)),"A modified standalone snapshot is rejected even when it remains valid INI");
  File.WriteAllLines(Path.Combine(output,"winapp2-test-results.txt"),checks.Concat(new[]{"ALL "+checks.Count+" WINAPP2 CHECKS PASSED","Only generated workspace fixtures were modified."}));return 0;
 }catch(Exception ex){File.WriteAllLines(Path.Combine(output,"winapp2-test-results.txt"),checks.Concat(new[]{ex.ToString()}));return 1;}
 }
}
}
